using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    public static class ArchiveSetsChecks
    {
        [Serializable]sealed class CheckResult{public string name;public bool passed;}
        [Serializable]sealed class Report{public bool passed;public string scope="Unity Editor native Hand/Book/region/check controls across ten updated Sets problems. Deadline fixtures are aged; rendered Android remains separate.";public List<CheckResult> checks=new List<CheckResult>();public List<string> errors=new List<string>();}
        static Report report;static ArchiveTopicSession session;static ArchiveTopicStation station;static ArchiveSetsPresentation art;static ArchiveSetsUI ui;static readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();static bool active,oldHunting;static double next;static GameObject restriction;
        public static string Status{get;private set;}="Idle";
        static ArchiveStationState State=>session.State.stations[6];
        public static void Begin(){if(!Application.isPlaying||Photon.Pun.PhotonNetwork.InRoom||active)throw new InvalidOperationException("Use offline Play Mode.");session=ArchiveTopicSession.Current;station=session.stations[6];art=station.GetComponent<ArchiveSetsPresentation>();ui=ArchiveTopicUI.Current.GetComponent<ArchiveSetsUI>();report=new Report();oldHunting=session.hunting.enabled;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);session.hunting.enabled=false;stack.Clear();stack.Push(Flow());next=0;active=true;EditorApplication.update+=Tick;Application.logMessageReceived+=Log;}
        static void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(message);}
        static void Tick(){if(!active)return;try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup<next)return;if(!Application.isPlaying)throw new Exception("Play stopped.");if(stack.Count==0){Finish(true);return;}var e=stack.Peek();if(!e.MoveNext()){stack.Pop();return;}if(e.Current is IEnumerator child)stack.Push(child);else next=EditorApplication.timeSinceStartup+(e.Current is float delay?delay:0);}catch(Exception ex){report.errors.Add(Status+": "+ex);Finish(false);}}
        static void Check(bool condition,string name){report.checks.Add(new CheckResult{name=name,passed=condition});if(!condition)throw new Exception(name);}
        static void Move(Vector3 p)=>ArchiveTopicPlayChecks.MoveTo(station,p);
        static void Book(){Move(ArchiveTopicStation.BookPosition+Vector3.back*1.7f);station.points.First(p=>p.role==ArchivePointRole.Book).Interact();}
        static IEnumerator Pick(int item){var q=session.Question(6);Move(station.CurrentItemPosition(item,q,State));station.points.First(p=>p.role==ArchivePointRole.Item&&p.index==item&&p.gameObject.activeSelf).Interact();yield return .055f;Check(State.carries.Any(c=>c.actor==-1&&c.item==item),"Hand picks physical element "+q.items[item]+" (#"+item+")");}
        static IEnumerator PlaceHeld(int region){Move(station.SlotPosition(region,session.Question(6)));station.points.First(p=>p.role==ArchivePointRole.Slot&&p.index==region).Interact();yield return .055f;Check(State.carries.Count==0,"Hand places into region "+region);}
        static IEnumerator Place(int item,int region){yield return Pick(item);yield return PlaceHeld(region);Check(State.placements[item]==region,"Physical block occupies only the selected region");}
        static IEnumerator Arrange(){var q=session.Question(6);var answer=ArchiveTopicChecks.Solution(q).placements;for(int i=0;i<answer.Length;i++)if(State.placements[i]>=0&&answer[i]<0){yield return Pick(i);session.Request(6,ArchiveAction.ReturnItem);yield return .055f;}for(int i=0;i<answer.Length;i++)if(answer[i]>=0&&State.placements[i]!=answer[i])yield return Place(i,answer[i]);}
        static IEnumerator Submit(){Move(Vector3.zero);ui.CheckButton.onClick.Invoke();yield return .2f;}
        static IEnumerator Preview(string name,bool reading){Move(new Vector3(0,0,6.1f));Player.LocalInstance.transform.rotation=station.transform.rotation*Quaternion.Euler(0,180,0);var look=Player.LocalInstance.GetComponentInChildren<CameraTargetController>();if(look!=null)look.SetViewAngles(32,station.transform.eulerAngles.y+180);if(reading)ArchiveTopicUI.Current.Open(station);else ArchiveTopicUI.Current.Close();yield return .35f;Directory.CreateDirectory("Temp/T7Polish");ScreenCapture.CaptureScreenshot("Temp/T7Polish/"+name+".png");yield return .3f;}
        static IEnumerator Flow(){
            Status="Book, review and penalty expiry";session.Initialize(314159);ArchiveTopicUI.Current.Close();Move(Vector3.zero);yield return .6f;var book=station.GetComponentInChildren<ArchiveAnimatedBook>();Check(book.OpenAmount<.01f&&!State.timerRunning&&session.TimerRemaining(State)==1080,"Arrival leaves the updated 18-minute Sets clock unstarted");ArchiveTopicUI.Current.Open(station);yield return .12f;Check(!State.timerRunning&&!Player.LocalInstance.IsMovementLocked,"Reader preview does not start time or lock the player");ArchiveTopicUI.Current.Close();Book();yield return .8f;double deadline=State.timerDeadline;Check(State.phase==1&&State.timerRunning&&State.timerLimit==session.setsChallengeTimeLimitSeconds*session.PacingMultiplier&&book.OpenAmount>.98f,"Book starts the existing shared session with solo's 18-minute challenge timing");
            var q=session.Question(6);Check(q.setSourceValues.Length==10&&q.items.Distinct().Count()==10,"Single membership starts ten distinct source values");ui.SelectItem(0);Check(ui.ReadingText.text.Contains(q.prompt),"Reader displays the complete current set definitions");ArchiveTopicUI.Current.Close();yield return .1f;var corners=new Vector3[4];ui.Objective.GetWorldCorners(corners);Check(ui.IsObjectiveVisible&&corners.Min(p=>p.x)>Screen.width*.60f,"Compact Sets objective stays on the right");yield return Preview("T7_Venn",false);yield return Preview("T7_Reader",true);ArchiveTopicUI.Current.Close();
            var solution=ArchiveTopicChecks.Solution(q).placements;int required=Array.FindIndex(solution,r=>r>=0);yield return Place(required,(solution[required]+1)%3);var ids=art.BlockRoots.Select(t=>t.GetInstanceID()).ToArray();yield return Submit();Check(State.round==0&&session.State.mistakes.Count==1&&State.setGrades[required]==-1,"Wrong membership records one actor mistake and grades its block red");Check(Math.Abs(State.timerDeadline-(deadline-10))<.000001&&ids.SequenceEqual(art.BlockRoots.Select(t=>t.GetInstanceID())),"Wrong submission deducts ten seconds without replacing blocks");
            State.timerDeadline=ArchiveTopicSession.TimerClock+4;int before=session.State.mistakes.Count;yield return 1.6f;yield return Submit();Check(State.timerExpired&&State.phase==0&&session.State.mistakes.Count==before+1,"Penalty exhausting the clock charges only the incorrect answer, without a second timeout mistake");var kept=State.placements.ToArray();Book();yield return .2f;Check(State.placements.SequenceEqual(kept)&&State.round==0&&session.TimerRemaining(State)>1079,"Book retry retains the current question and physical assignments");deadline=State.timerDeadline;yield return Arrange();yield return 1.6f;yield return Submit();Check(State.round==1&&State.phase==1&&State.timerDeadline==deadline,"Second problem starts automatically on the same challenge clock");Check(session.Question(6).setEntry!=q.setEntry,"Two problems in the same challenge never repeat the bank entry");yield return Arrange();yield return Submit();Check(State.round==2&&State.phase==0&&!State.timerRunning&&session.TimerRemaining(State)==1080,"Two successes finish the challenge and reset the waiting clock to 18 minutes");Check(session.ActiveTopic==6&&!session.CanStartTopic(0),"Book gates still reserve the unfinished team topic");
            Status="Disjoint and shared sets";for(int r=2;r<6;r++){if(State.phase==0){Book();yield return .2f;}q=session.Question(6);Check(q.setGroup==r/2&&q.items.Length==10,"Problem "+(r+1)+" uses the updated ten-value source");if(r==3){yield return Place(Array.FindIndex(ArchiveTopicChecks.Solution(q).placements,p=>p>=0),0);kept=State.placements.ToArray();State.timerDeadline=ArchiveTopicSession.TimerClock-.01;before=session.State.mistakes.Count;yield return .3f;Check(State.timerExpired&&State.round==3&&State.placements.SequenceEqual(kept)&&session.State.mistakes.Count==before+1,"Timeout keeps the first solved problem and current second-problem work");Book();yield return .2f;}yield return Arrange();yield return Submit();Check(State.round==r+1,"Native set membership problem "+(r+1)+" advances shared progress");}
            Status="Replenishing physical copies";Book();yield return .2f;q=session.Question(6);Check(q.setGroup==3&&q.setSourceValues.Length==10&&q.items.Length==60&&art.BlockRoots.Count(t=>t.gameObject.activeSelf)==10,"Five-region problem renders ten supply blocks from a bounded logical copy pool");string shared=q.regionValues[2][0];int source=Array.IndexOf(q.setSourceValues,shared),first=ArchiveSetsPresentation.AvailableCopy(source,q,State);yield return Pick(first);int replacement=ArchiveSetsPresentation.AvailableCopy(source,q,State);Check(replacement==first+10&&art.BlockRoots.Any(t=>t.name=="Set_Element_"+replacement&&t.gameObject.activeSelf),"Source pickup immediately leaves a new same-number block");yield return PlaceHeld(0);yield return Place(replacement,1);int third=ArchiveSetsPresentation.AvailableCopy(source,q,State);yield return Place(third,2);Check(new[]{first,replacement,third}.Distinct().Count()==3&&State.placements[first]==0&&State.placements[replacement]==1&&State.placements[third]==2,"One shared value uses three distinct physical copies for full A, full B and intersection");
            int supply=ArchiveSetsPresentation.AvailableCopy(source,q,State);yield return Pick(first);Check(ArchiveSetsPresentation.AvailableCopy(source,q,State)==supply,"Picking a placed block creates no extra source copy");yield return PlaceHeld(0);Move(station.ItemPosition(source,q));int revision=State.revision;int dormant=source+50;session.Request(6,ArchiveAction.Pick,dormant);yield return .1f;Check(State.revision==revision&&State.carries.Count==0,"Authority rejects an invisible dormant copy ID even near the source");yield return Place(supply,0);yield return Submit();Check(State.setGrades[first]==1&&State.setGrades[supply]==-1,"Duplicate in one tray is red while the valid physical copy remains green");yield return Pick(supply);session.Request(6,ArchiveAction.ReturnItem);yield return .1f;Check(State.placements[supply]==-1&&State.setGrades[first]==1,"Returning an extra copy clears only that block's grade");kept=State.placements.ToArray();State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Book();yield return .2f;Check(State.placements.SequenceEqual(kept),"Timeout and retry retain each independent copied-block assignment");yield return Preview("T7_FiveRegions",false);yield return Arrange();yield return 1.6f;yield return Submit();Check(State.round==7&&State.phase==1,"First five-region problem advances directly to the second");yield return Arrange();yield return Submit();Check(State.round==8&&State.phase==0,"Two five-region problems complete challenge four");
            Status="Preplaced complement correction";Book();yield return .2f;q=session.Question(6);Check(q.setGroup==4&&q.items.Length==9&&State.placements.SequenceEqual(q.setInitialPlacements)&&!ArchiveTopicQuestions.Validate(q,State,out _),"Complement starts nine existing values in the updated incorrect arrangement");Check(station.workRoot.Cast<Transform>().Count(t=>t.name=="Named_Set_Circle")==1&&station.workRoot.Cast<Transform>().All(t=>!t.name.StartsWith("Element_Supply_")),"Only the named circle appears inside U, without a duplicate-block spawner");for(int i=0;i<9;i++)Check(ArchiveSetsPresentation.InsideRegion(State.placements[i],station.CurrentItemPosition(i,q,State),q),"Preplaced value remains within the visible universal boundary");yield return Preview("T7_Complement",false);ids=art.BlockRoots.Select(t=>t.GetInstanceID()).ToArray();yield return Submit();Check(State.setGrades.Any(g=>g<0)&&State.setGrades.Any(g=>g>0)&&ids.SequenceEqual(art.BlockRoots.Select(t=>t.GetInstanceID())),"Complement review marks misplaced values red and keeps correct values green without replacing objects");
            int wrong=Array.FindIndex(State.setGrades,g=>g<0);yield return Pick(wrong);restriction=new GameObject("T7 capture fixture");Player.LocalInstance.AcquireMovementLock(restriction,"T7 captured",Player.LocalInstance.transform.position,100);yield return .3f;Check(!session.CanAct(-1)&&State.carries.Count==0&&State.placements[wrong]>=0&&!ui.IsObjectiveVisible,"Capture releases a carried complement value back inside U and hides the objective");Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);restriction=null;yield return Pick(wrong);session.Request(6,ArchiveAction.ReturnItem);yield return .1f;Check(State.placements[wrong]==q.setInitialPlacements[wrong]&&art.BlockRoots.Count(t=>t.gameObject.activeSelf)==9,"Return block preserves all nine unique complement values inside U");yield return Arrange();yield return 1.6f;yield return Submit();Check(State.round==9&&State.phase==1,"Second complement problem follows automatically");yield return Arrange();yield return Submit();Check(State.round==10&&State.phase==2&&!State.timerRunning&&session.ActiveTopic==-1,"Ten problems complete all five Sets challenges and release the next topic");float remaining=session.TimerRemaining(State);yield return .2f;Check(session.TimerRemaining(State)==remaining&&session.State.stations.Where(s=>s.topic!=6).All(s=>s.round==0&&s.timerAttempt==0),"Completion freezes time and preserves every other topic");Check(!Player.LocalInstance.IsMovementLocked&&Time.timeScale==1&&report.errors.Count==0,"Reading and correction never pause or lock normal player controls; no runtime errors");Status="Passed";
        }
        public static string ValidateVariants(){var catalog=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(ArchiveTopicSetup.Folder+"/Archive_Topic_Catalog.asset");var solo=ArchiveSetsPolish.ReadSoloBanks();var checks=new List<CheckResult>();var failures=new List<string>();int cases=0;Action<bool,string> test=(ok,name)=>{checks.Add(new CheckResult{name=name,passed=ok});if(!ok)failures.Add(name);};
            try{for(int group=0;group<5;group++){test(catalog.sets[group].questions.Count==solo[group].questions.Count,"Updated solo bank size "+group);for(int entry=0;entry<solo[group].questions.Count;entry++){int g=group,e=entry;int seed=Enumerable.Range(1,4096).First(s=>ArchiveTopicQuestions.Build(catalog,6,g*2,s).setEntry==e);var q=ArchiveTopicQuestions.Build(catalog,6,group*2,seed);var data=solo[group].questions[entry];var good=ArchiveTopicChecks.Solution(q);string id="Group "+(group+1)+" / entry "+(entry+1);cases++;test(q.setA.OrderBy(v=>v).SequenceEqual((data.a??Array.Empty<string>()).OrderBy(v=>v))&&q.setB.OrderBy(v=>v).SequenceEqual((data.b??Array.Empty<string>()).OrderBy(v=>v)),id+" matches updated solo sets");test(ArchiveTopicQuestions.Validate(q,good,out _),id+" accepts the complete mathematical arrangement");test(ArchiveTopicQuestions.SetPlacementGrades(q,good).All(n=>n>=0),id+" grades correct placements green");var bad=ArchiveTopicChecks.Solution(q);int item=Array.FindIndex(bad.placements,r=>r>=0);bad.placements[item]=(bad.placements[item]+1)%q.slots.Length;test(!ArchiveTopicQuestions.Validate(q,bad,out _),id+" rejects a wrong membership region");test(ArchiveTopicQuestions.Build(catalog,6,group*2+1,seed).setEntry!=entry,id+" selects two distinct bank questions");test(q.items.Length<=64&&q.setSourceValues.Distinct().Count()==q.setSourceValues.Length,id+" stays within the source/copy budget");var cells=ArchiveSetsPresentation.Cells(q);test(cells.SelectMany((points,r)=>points.Select(p=>ArchiveSetsPresentation.InsideRegion(r,p,q))).All(x=>x),id+" places blocks inside their visible region geometry");if(group==3){test(q.items.Length==60&&Enumerable.Range(0,q.items.Length).Count(i=>ArchiveSetsPresentation.Visible(i,q,new ArchiveStationState{placements=Enumerable.Repeat(-1,q.items.Length).ToArray()}))==10,id+" initially renders one replenishing block per value");}if(group==4){var initial=new ArchiveStationState{placements=q.setInitialPlacements.ToArray()};test(q.items.Length==9&&q.items.OrderBy(v=>v).SequenceEqual(data.universe.OrderBy(v=>v))&&!ArchiveTopicQuestions.Validate(q,initial,out _),id+" starts all nine U values with deliberate misplaced elements");}}}
            var font=AssetDatabase.LoadAssetAtPath<TMPro.TMP_FontAsset>(ArchiveSetsPolish.ReadingFontPath);test(font!=null&&"A ∩ B − U →".Where(c=>!char.IsWhiteSpace(c)).All(c=>font.HasCharacter(c,true,false)),"T7 reading font supports all Sets notation through saved math fallbacks");
            }catch(Exception ex){failures.Add(ex.ToString());}var result=new{passed=failures.Count==0,updatedSoloCases=cases,checks=checks,failures=failures};Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T7SetVariants.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return(result.passed?"Passed":"Failed")+": "+cases+" updated solo cases / "+checks.Count+" checks";
        }
        static void Finish(bool ok){active=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;stack.Clear();if(restriction!=null){Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);}if(session!=null&&Application.isPlaying){session.hunting.enabled=oldHunting;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);ArchiveTopicUI.Current.Close();}report.passed=ok&&report.errors.Count==0&&report.checks.All(c=>c.passed);Status=report.passed?"Passed":"Failed";Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T7PolishPlayMode.json",JsonUtility.ToJson(report,true));Debug.Log("T7 Sets: "+Status+" / "+report.checks.Count);}
    }
}
